<?php
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin | RodnyPHP</title><link rel="stylesheet" href="../assets/css/style.css"></head>
<body><header class="site-header"><div class="container header-inner"><a class="brand" href="../index.php">RodnyPHP</a><nav class="main-nav"><a href="../index.php">Portfolio</a></nav></div></header>
<main class="container"><section class="panel"><p class="eyebrow">PHP Admin</p><h1>Banner Manager</h1><form id="form" class="form-grid"><label>Title<input id="title" required></label><label>Subtitle<textarea id="subtitle"></textarea></label><label>Link<input id="link" value="../index.php"></label><label>Image URL<input id="image"></label><label>Active<select id="active"><option value="0">No</option><option value="1">Yes</option></select></label><button class="button primary">Save Banner</button></form><p id="status"></p></section><section class="panel"><h2>Saved banners</h2><div id="list"></div></section></main>
<script>
const api='banner-api.php',form=document.querySelector('#form'),list=document.querySelector('#list'),status=document.querySelector('#status');let rows=[];
async function load(){try{const r=await fetch(api);if(!r.ok)throw Error('API request failed');rows=await r.json();list.innerHTML='';rows.forEach(x=>{const e=document.createElement('article');e.className='card';e.innerHTML='<h3></h3><p></p><button data-id="'+x.id+'">Delete</button>';e.querySelector('h3').textContent=x.title+(x.active?' (active)':'');e.querySelector('p').textContent=x.subtitle||'';e.querySelector('button').onclick=()=>remove(x.id);list.append(e)});status.textContent='Connected';}catch(e){status.textContent=e.message}}async function remove(id){if(!confirm('Delete banner?'))return;await fetch(api+'?id='+encodeURIComponent(id),{method:'DELETE'});load()}form.onsubmit=async e=>{e.preventDefault();const r=await fetch(api,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:title.value,subtitle:subtitle.value,link:link.value,image:image.value,active:active.value==='1'})});status.textContent=(await r.json()).message||'Saved';form.reset();load()};load();
</script></body></html>